local formatTableModule = require(script.Parent.Parent.formatTable)
local formatTable = formatTableModule.formatTable

return function(plasma)
	return plasma.widget(function(debugger, objectStack, operations)
		local custom = debugger._customWidgets
		local style = plasma.useStyle()
		local create = plasma.create
		local object = objectStack[#objectStack]

		local closed = plasma
			.window({
				title = "Node inspect",
				closable = true,
				minSize = Vector2.new(50, style.panelHeight),
				maxSize = Vector2.new(1150, style.panelHeight)
			}, function()
				local path = object.value:GetPath()
				if #operations > 0 then
					path = path .. "?" .. operations[1].i.object.Name
					-- path = path
				end
				custom.rect(function()
					plasma.row(function()
						custom.label1(object.value:GetId())
						if #object.value._children > 0 then
							local count = object.value._children[1]:GetCount()
							if count then
								custom.label1(count)
							end
						end
					end)
					plasma.row(function()
						local l:TextBox = custom.label1(path, {
							Size = UDim2.fromOffset(504, 0),
							TextXAlignment = Enum.TextXAlignment.Left
						})
						-- 460
						-- if custom.button1("Copy", {width = 100}):clicked() then
						-- 	l:CaptureFocus()
						-- 	l.CursorPosition = string.len(l.Text)
						-- 	l.SelectionStart = 1
						-- end
						if custom.button1("Back", {width = 100}):clicked() then
							table.remove(objectStack, #objectStack)
							table.clear(operations)
						end
					end)
				end, {
					Size = UDim2.fromOffset(630, 0)
				})
				custom.scrollframe(function()
					custom.rect(function()
						local qlist = {}
						local list = object.value:GetAbilities()
						if #list.queries > 0 then
							for i, v in pairs(list.queries) do
								table.insert(qlist, {
									text = v.Name .. (v.IsQueryObserver and " ⭐" or ""),
									selected = false,
									object = v
								})
							end
						end
						local alist = {}
						if #list.actions > 0 then
							for i, v in pairs(list.actions) do
								table.insert(alist, {
									text = v.Name,
									selected = false,
									object = v
								})
							end
						end
						local vlist = {}
						if #list.validators > 0 then
							for i, v in pairs(list.validators) do
								table.insert(vlist, {
									text = v.Name,
									selected = false,
									object = v
								})
							end
						end
						local selected = custom.operationList({
							Query = qlist,
							Action = alist,
							Validate = vlist,
						}, custom, {width = 270}):selected()
						if selected then
							table.clear(operations)
							debugger.ExecuteRes = nil
							operations[1] = selected
						end


						local list = object.value:QueryList()
						if #list > 1 then
							local selectedState = plasma.table(list, {
								headings = true,
								selectable = true,
								font = Enum.Font.Gotham
							}):selected()
							if selectedState then
								local idx = selectedState[1]
								local nextObject = object.value:GetChildrenFromSorted(idx)
								if nextObject then
									local selectedItem = {
										key = selectedState[2],
										icon = selectedState.icon,
										value = nextObject
									}
									table.insert(objectStack, selectedItem)
									table.clear(operations)
								else
									selectedState = nil
								end
							end
						end


					end, {
						Size = UDim2.fromOffset(630, 0),
						FillDirection = Enum.FillDirection.Horizontal
					})
				end, {
					Size = UDim2.new(1, 0, 1, -110)
				})
			end)
			:closed()

		if closed then
			debugger._nodeViewOpen = false

			return closed
		end
		return nil
	end)
end
